namespace sv_68945d35b0d44690b0877c89021a24f8;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<span class="badge" style="background-color: @(Theme?.AccentColor ?? "#0d6efd")">
    @(Theme?.Theme.ToString() ?? "Light")
</span>

<button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme">
    Toggle Theme
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task CycleTheme()
    {
        if (Theme is null) return;

        Theme.Theme = Theme.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            Theme.System => Theme.Light,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync(Theme);
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

@if (Theme is not null)
{
    <div class="mb-3">
        <label class="form-label">Theme</label>
        <select class="form-select" value="@Theme.Theme" @onchange="OnThemeChanged">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <option value="@t">@t</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@Theme.AccentColor" @onchange="OnAccentChanged" />
    </div>

    <p>
        Current: <strong>@Theme.Theme</strong> /
        <span style="color: @Theme.AccentColor">@Theme.AccentColor</span>
    </p>
}

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Theme is null) return;
        Theme.Theme = Enum.Parse<Theme>(e.Value?.ToString() ?? "Light");
        await ThemeSource.NotifyChangedAsync(Theme);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        if (Theme is null) return;
        Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd";
        await ThemeSource.NotifyChangedAsync(Theme);
    }
}

