@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<span class="badge" style="background-color: @(Theme?.AccentColor ?? "#0d6efd")">
    @(Theme?.Theme.ToString() ?? "Light")
</span>

<button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme">
    Toggle Theme
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task CycleTheme()
    {
        if (Theme is null) return;

        Theme.Theme = Theme.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            Theme.System => Theme.Light,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync(Theme);
    }
}

